require __DIR__.'/includes/bootstrap.php';require_login();require_member($pdo);$memberId=current_member_id();
$types=['cables'=>['Cabluri electrice','Trasee cabluri, doze și puncte importante din pereți.'],'plumbing'=>['Instalații apă','Țevi, scurgeri, robineți și trasee ascunse.'],'finishes'=>['Materiale & finisaje','Coduri de vopsea, gresie, parchet, silicon și materiale folosite.']];$type=$_GET['type']??'cables';if(!isset($types[$type]))$type='cables';$message='';$error='';
function house_store_photo(array $file): ?string {if(empty($file['tmp_name'])||!is_uploaded_file($file['tmp_name']))return null;if(($file['size']??0)>15*1024*1024)throw new RuntimeException('Poza este prea mare. Maxim 15 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);$ok=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/heic'=>'heic','image/heif'=>'heif'];if(!isset($ok[$mime]))throw new RuntimeException('Format imagine nesuportat.');$dir=__DIR__.'/storage/house';if(!is_dir($dir))mkdir($dir,0700,true);$path='storage/house/'.bin2hex(random_bytes(16)).'.'.$ok[$mime];if(!move_uploaded_file($file['tmp_name'],__DIR__.'/'.$path))throw new RuntimeException('Nu am putut salva poza.');return $path;}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$a=$_POST['action']??'';if($a==='add'){$title=trim($_POST['title']??'');if(!$title)throw new RuntimeException('Completează titlul.');$img=house_store_photo($_FILES['image']??[]);$pdo->prepare('INSERT INTO house_technical_records(record_type,title,area,details,measurements,image_path,created_by_member_id) VALUES(?,?,?,?,?,?,?)')->execute([$type,$title,trim($_POST['area']??'')?:null,trim($_POST['details']??'')?:null,trim($_POST['measurements']??'')?:null,$img,$memberId]);$message='Înregistrarea a fost adăugată.';}if($a==='delete'){$id=(int)$_POST['id'];$q=$pdo->prepare('SELECT image_path FROM house_technical_records WHERE id=? AND record_type=?');$q->execute([$id,$type]);$p=$q->fetchColumn();$pdo->prepare('DELETE FROM house_technical_records WHERE id=? AND record_type=?')->execute([$id,$type]);if($p&&str_starts_with($p,'storage/house/')&&is_file(__DIR__.'/'.$p))@unlink(__DIR__.'/'.$p);$message='Înregistrarea a fost ștearsă.';}}catch(Throwable $e){$error=$e->getMessage();}}
$s=$pdo->prepare('SELECT r.*,m.name creator FROM house_technical_records r LEFT JOIN family_members m ON m.id=r.created_by_member_id WHERE record_type=? ORDER BY r.id DESC');$s->execute([$type]);$items=$s->fetchAll();$pageTitle=$types[$type][0];$active='more';$backUrl='/home.php';require __DIR__.'/includes/layout_top.php';?>
<?php if($message):?><div class="alert success"><?=e($message)?></div><?php endif;?><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?>
