<div class="technical-record-grid"><?php foreach($items as $r):?><article class="technical-record-card"><?php if($r['image_path']):?><img src="/house-media.php?id=<?=$r['id']?>" alt="" loading="lazy"><?php endif;?><div class="technical-record-body"><b><?=e($r['title'])?></b><?php if($r['area']):?><span><?=e($r['area'])?></span><?php endif;?><?php if($r['measurements']):?><small><?=e($r['measurements'])?></small><?php endif;?><?php if($r['details']):?><p><?=nl2br(e($r['details']))?></p><?php endif;?><form method="post" onsubmit="return confirm('Ștergi înregistrarea?');"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn danger-outline small">Șterge</button></form></div></article><?php endforeach;?><?php if(!$items):?><div class="empty">Nu ai adăugat încă nimic aici.</div><?php endif;?></div>
